"""genui without FastAPI: a plain Flask (WSGI) server using genui.stream.encode().

Run:  pip install genui-py flask openai
      OPENAI_API_KEY=... flask --app flask_app run --port 8000
The same pattern works in Django (StreamingHttpResponse), Bottle, or any sync framework.
"""
import asyncio
import os
from pathlib import Path

from flask import Flask, Response, request, stream_with_context
from openai import OpenAI

from genui import Library, parse_run_input
from genui.stream import encode

# spec.json is generated by the React frontend (`npm run generate` in examples/fastapi-react/frontend).
SPEC = Path(__file__).resolve().parents[1] / "fastapi-react" / "backend" / "spec.json"
library = Library.from_spec(SPEC)
SYSTEM_PROMPT = library.system_prompt()

client = OpenAI()  # sync client; OPENAI_BASE_URL=http://localhost:11434/v1 for Ollama
MODEL = os.environ.get("MODEL", "gpt-5.5-mini")
app = Flask(__name__)


def iter_sync(agen):
    """encode() is an async generator; WSGI wants a sync iterator. Drive it on a private event loop."""
    loop = asyncio.new_event_loop()
    try:
        while True:
            try:
                yield loop.run_until_complete(agen.__anext__())
            except StopAsyncIteration:
                break
    finally:
        loop.run_until_complete(agen.aclose())
        loop.close()


@app.post("/api/chat")
def chat():
    run = parse_run_input(request.get_json())
    stream = client.chat.completions.create(  # a sync stream is fine: encode() accepts sync iterables
        model=MODEL,
        messages=[{"role": "system", "content": SYSTEM_PROMPT}, *run.messages],
        stream=True,
    )
    sse = encode(stream, "ag-ui", thread_id=run.thread_id, run_id=run.run_id)
    return Response(stream_with_context(iter_sync(sse)), mimetype="text/event-stream",
                    headers={"Cache-Control": "no-cache, no-transform", "X-Accel-Buffering": "no"})
